class Review:
    def __init__(self, username, rating):
        rating = int(rating)
        if not (1 <= rating <= 5):
            raise ValueError("Rating must be between 1 and 5")
        self.username = username
        self.rating = rating
    def __eq__(self, other):
        return isinstance(other, Review) and self.username == other.username
    def __hash__(self):
        return hash(self.username)

class Book:
    def __init__(self, title, author, year):
        self.title = title
        self.author = author
        self.year = year
        self._reviews_dict = {}
    def add_review(self, review):
        if not isinstance(review, Review):
            raise TypeError("Review must be an instance of the Review class")
        self._reviews_dict[review.username] = review
    def get_reviews(self):
        return list(self._reviews_dict.values())
    def average_rating(self):
        reviews = self.get_reviews()
        if not reviews:
            return 0.0
        return sum(r.rating for r in reviews) / len(reviews)

def main():
    title = input()
    author = input()
    year = input()
    book = Book(title, author, year)
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line == "END":
            break
        if line.startswith("ADD "):
            _, username, rating = line.split()
            book.add_review(Review(username, int(rating)))
        elif line == "LIST":
            for review in book.get_reviews():
                print(f"{review.username} {review.rating}")
        elif line == "AVG":
            avg = book.average_rating()
            print(f"{avg:.2f}")

if __name__ == "__main__":
    main()

class Node:
    def __init__(self, value, next_node=None, prev_node=None):
        self.value = value
        self.next = next_node
        self.prev = prev_node

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def add_at_head(self, value):
        new_node = Node(value, self.head, None)
        if self.head:
            self.head.prev = new_node
        self.head = new_node
        if not self.tail:
            self.tail = new_node
        self.size += 1

    def add_at_tail(self, value):
        new_node = Node(value, None, self.tail)
        if self.tail:
            self.tail.next = new_node
        self.tail = new_node
        if not self.head:
            self.head = new_node
        self.size += 1

    def remove_from_head(self):
        if not self.head:
            return None
        removed_value = self.head.value
        self.head = self.head.next
        if self.head:
            self.head.prev = None
        else:
            self.tail = None
        self.size -= 1
        return removed_value

    def remove_from_tail(self):
        if not self.tail:
            return None
        removed_value = self.tail.value
        self.tail = self.tail.prev
        if self.tail:
            self.tail.next = None
        else:
            self.head = None
        self.size -= 1
        return removed_value

    def traverse_forward(self):
        result = []
        current = self.head
        while current:
            result.append(str(current.value))
            current = current.next
        return result

    def traverse_backward(self):
        result = []
        current = self.tail
        while current:
            result.append(str(current.value))
            current = current.prev
        return result

    def get_size(self):
        return self.size

def main():
    dll = DoublyLinkedList()
    while True:
        try:
            line = input()
        except EOFError:
            break
        if not line:
            continue
        if line == 'exit':
            break
        command = line.strip().split()
        if command[0] == 'add_head':
            dll.add_at_head(int(command[1]))
        elif command[0] == 'add_tail':
            dll.add_at_tail(int(command[1]))
        elif command[0] == 'remove_head':
            val = dll.remove_from_head()
            print(val)
        elif command[0] == 'remove_tail':
            val = dll.remove_from_tail()
            print(val)
        elif command[0] == 'traverse_forward':
            res = dll.traverse_forward()
            print(' '.join(res))
        elif command[0] == 'traverse_backward':
            res = dll.traverse_backward()
            print(' '.join(res))
        elif command[0] == 'size':
            print(dll.get_size())

