public class ClassesInstancesObjects {

    public static String binMaxInt() {
        return Integer.toBinaryString(Integer.MAX_VALUE);
    }

    public static String binDiffMax(Integer i) {
        return Integer.toBinaryString(Integer.MAX_VALUE - i.intValue());
    }

    public static String mutant(String a, String b) {
        int aHalf = a.length()/2 + a.length()%2;
        int bHalf = b.length()/2;
        return a.substring(0, aHalf) + b.substring(bHalf);
    }

    public static String triMutant(String a, String b, String c) {
        int aT = a.length()/3 + ((a.length()%3)>0 ? 1 : 0); // first third length
        int bT = b.length()/3;
        int b2T = bT + (b.length()%3 > 1 ? 1 : 0);
        int cT = c.length()/3;
        int c2T = c.length()-cT;

        // avoid boolean logic: use arithmetic
        int la = a.length();
        int lb = b.length();
        int lc = c.length();

        // Obtain start and end indices for thirds
        int a1 = (la + 2) / 3;
        int b1 = lb / 3;
        int b2 = (lb + 1) / 3;
        int c2 = lc - (lc / 3);

        return a.substring(0, a1)
                + b.substring(b1, lb - b2)
                + c.substring(c2);
    }

    // Teaching-friendly solution: works for all cases, including strings of length 1
    public static String swapEnds(String a) {
        if (a.length() < 2) return a;
        return a.substring(a.length()-1) + a.substring(1, a.length()-1) + a.substring(0, 1);
    }

    public static int indexOf2nd(String haystack, String needle) {
        int first = haystack.indexOf(needle);
        if (first == -1) return -1;
        int second = haystack.indexOf(needle, first + needle.length());
        return second;
    }

    public static int indexOf2ndLast(String haystack, String needle) {
        int last = haystack.lastIndexOf(needle);
        if (last == -1) return -1;
        String cut = haystack.substring(0, last);
        int secondLast = cut.lastIndexOf(needle);
        return secondLast;
    }

    // Only for "reduplicates" as described in prompt (a word is two identical halves)
    public static boolean reduplicates(String word) {
        int len = word.length();
        String a = word.substring(0, len/2);
        String b = word.substring(len/2);
        return word.length() % 2 == 0 && a.equals(b);
    }

    public static boolean binContains(Integer i, String p) {
        String bin = Integer.toBinaryString(i);
        return bin.indexOf(p) != -1;
    }

    public static boolean isPalindrome(Integer i) {
        String bin = Integer.toBinaryString(i);
        String rev = new StringBuilder(bin).reverse().toString();
        return bin.equals(rev);
    }

    public static boolean isAnagram(Integer a, Integer b) {
        String sa = Integer.toBinaryString(a);
        String sb = Integer.toBinaryString(b);
        char[] ca = sa.toCharArray();
        char[] cb = sb.toCharArray();
        java.util.Arrays.sort(ca);
        java.util.Arrays.sort(cb);
        return new String(ca).equals(new String(cb));
    }

    public static boolean cubeContainsSelf(Integer i) {
        String self = i.toString();
        String cube = Integer.toString(i*i*i);
        return cube.indexOf(self) != -1;
    }

    // No conditionals/logical operators: use Double.max in a chain
    public static Double maxValue(Double a, Double b, Double c, Double d) {
        return Double.max(Double.max(a, b), Double.max(c, d));
    }

    public static Integer middleValue(Integer a, Integer b, Integer c) {
        java.util.List<Integer> list = java.util.Arrays.asList(a, b, c);
        java.util.Collections.sort(list);
        return list.get(1);
    }

    public static Integer middleValue(Integer a, Integer b, Integer c, Integer d, Integer e) {
        java.util.List<Integer> list = java.util.Arrays.asList(a, b, c, d, e);
        java.util.Collections.sort(list);
        return list.get(2);
